// GENERATED by scripts/build.js from lib/resources/toolconfig.js. Edit that file, then run `npm run build`.
/**
 * Tool config files: a tool arrives as <name>.html (the tool) + <name>.json (its page text). This reads
 * the JSON (schema version 1, below), maps it onto the admin form's fields and lists every problem with
 * the field it belongs to, so the admin can show it in place. Nothing is dropped silently: a value that
 * can't go in the form (wrong type, invalid subject or level, unknown key) is named in a problem, and the
 * original file is kept in the bucket either way.
 *
 * Version 1:
 *   { version: 1, file: "<name>.html", subject, levels[], courseTags[],
 *     en: { title, slug, description, intro, howTo[], keyIdeas[], faq[{q, a}], keywords[] },
 *     es: { same keys },
 *     files: [{ file: "<Name>.pdf", en: "label", es: "label" }],   optional: PDFs, in display order
 *     related: ["<slug-en>", ...] }                                 optional: shown first under "Related"
 * intro: a blank line between paragraphs. keyIdeas (and the other text) may contain $...$ LaTeX.
 * A config without `files` or `related` leaves those as they are (fields.files / fields.related undefined).
 */
"use strict";

const M = require("./model.js");

const VERSION = 1;
const MAX_BYTES = 256 * 1024;
const TOP_KEYS = ["version", "file", "subject", "levels", "courseTags", "relatedExamPage", "en", "es", "files", "related"];
const LANG_KEYS = ["title", "slug", "description", "intro", "howTo", "keyIdeas", "faq", "keywords"];
const REQUIRED = ["title", "slug", "description", "intro", "howTo", "keyIdeas"];
const LABEL = { title: "title", slug: "slug", description: "description", intro: "intro", howTo: "how-to steps", keyIdeas: "key ideas", faq: "FAQ", keywords: "keywords" };

const show = (v) => { const s = JSON.stringify(v); return s && s.length > 80 ? `${s.slice(0, 77)}…` : s; };
const baseName = (name) => String(name || "").split(/[\\/]/).pop();
const stem = (name) => baseName(name).replace(/\.(html?|json)$/i, "");

/** Parses JSON text; throws an Error with a plain message (and the line/column when Node gives a position). */
function parseJson(text) {
  try { return JSON.parse(String(text).replace(/^﻿/, "")); }
  catch (e) {
    const m = String(e.message).match(/position (\d+)/);
    let where = "";
    if (m) {
      const before = String(text).replace(/^﻿/, "").slice(0, Number(m[1]));
      where = ` (line ${before.split("\n").length}, column ${before.length - before.lastIndexOf("\n")})`;
    }
    throw new Error(`The config isn't valid JSON${where}: ${String(e.message).replace(/^.*?: /, "").replace(/ in JSON at position \d+.*$/, "")}.`);
  }
}

/** The next free slug: base-2, base-3, ... (current and old slugs of other resources, same language). */
function freeSlug(base, lang, others) {
  const taken = (s) => others.some((o) => M.slugOf(o, lang) === s || M.historyOf(o, lang).includes(s));
  for (let i = 2; i < 1000; i++) { const s = `${base}-${i}`.slice(0, M.SLUG_MAX); if (!taken(s)) return s; }
  return `${base}-${Date.now().toString(36)}`;
}

/**
 * Reads a config. Options: htmlName (the tool file it came with, or the resource's current one),
 * others (every other resource, for slug clashes), selfId.
 * Returns { ok, fields, problems, file } where
 *   fields   = the form's shape: { slugEn, slugEs, subject, levels, courseTags, en: {...}, es: {...} }
 *              (null when the file can't be used at all: bad JSON, not an object, unknown version)
 *   problems = [{ field, message, level: "error" | "warning", suggestion? }]
 *              field: "json" | "version" | "file" | "subject" | "levels" | "courseTags" | "<lang>.<key>" | "<lang>"
 *                     | "files" | "related"
 *   fields.files   = [{ name, labelEn, labelEs }] (only when the config has "files")
 *   fields.related = ["<slug-en>"] (only when the config has "related")
 */
function readConfig(text, { htmlName = "", others = [], selfId = "" } = {}) {
  const problems = [];
  const add = (field, message, level = "error", extra = {}) => problems.push({ field, message, level, ...extra });
  if (Buffer.byteLength(String(text)) > MAX_BYTES) return { ok: false, fields: null, problems: [{ field: "json", level: "error", message: `The config is over ${MAX_BYTES / 1024} KB.` }] };
  let c;
  try { c = parseJson(text); }
  catch (e) { return { ok: false, fields: null, problems: [{ field: "json", level: "error", message: e.message }] }; }
  if (!c || typeof c !== "object" || Array.isArray(c)) return { ok: false, fields: null, problems: [{ field: "json", level: "error", message: "The config must be a JSON object ({ ... })." }] };
  if (c.version !== VERSION) {
    add("version", c.version === undefined ? `The config has no "version". This admin reads version ${VERSION}; add "version": ${VERSION}.`
      : `Unknown config version ${show(c.version)}. This admin reads version ${VERSION}, so nothing was filled.`);
    return { ok: false, fields: null, problems, file: typeof c.file === "string" ? c.file : "" };
  }
  for (const k of Object.keys(c)) if (!TOP_KEYS.includes(k)) add("json", `Unknown key "${k}" (not used; it stays in the stored config file).`, "warning");

  // file <-> the uploaded tool
  const file = typeof c.file === "string" ? c.file.trim() : "";
  if (!file) add("file", 'The config has no "file" (the tool\'s .html file name).', "warning");
  else if (htmlName && baseName(file) !== baseName(htmlName)) add("file", `The config is for "${baseName(file)}", but the tool file is "${baseName(htmlName)}". Check that they belong together.`);

  const others_ = others.filter((o) => o.id !== selfId);
  const fields = { slugEn: "", slugEs: "", subject: "", levels: [], courseTags: [], en: {}, es: {} };

  // subject
  if (c.subject === undefined || c.subject === "") add("subject", 'Missing "subject".');
  else if (typeof c.subject !== "string" || !M.SUBJECTS[c.subject]) add("subject", `Subject ${show(c.subject)} isn't one of: ${Object.keys(M.SUBJECTS).join(", ")}. Pick one.`);
  else fields.subject = c.subject;

  // levels
  if (!Array.isArray(c.levels)) add("levels", c.levels === undefined ? 'Missing "levels".' : `"levels" must be a list, got ${show(c.levels)}.`);
  else {
    const bad = c.levels.filter((l) => !M.LEVELS[l]);
    fields.levels = [...new Set(c.levels.filter((l) => M.LEVELS[l]))];
    if (bad.length) add("levels", `Not a valid level: ${bad.map(show).join(", ")}. Valid: ${Object.keys(M.LEVELS).join(", ")}.`);
    if (!c.levels.length) add("levels", "No levels listed.");
  }

  // course tags
  if (c.courseTags !== undefined) {
    if (!Array.isArray(c.courseTags)) add("courseTags", `"courseTags" must be a list, got ${show(c.courseTags)}.`);
    else {
      const bad = c.courseTags.filter((t) => typeof t !== "string" || /,/.test(t));
      fields.courseTags = c.courseTags.filter((t) => typeof t === "string" && !/,/.test(t)).map((t) => t.trim()).filter(Boolean);
      if (bad.length) add("courseTags", `Course tags must be text without commas: ${bad.map(show).join(", ")}.`);
    }
  }

  // related exam page ("See also"), optional
  if (c.relatedExamPage !== undefined && c.relatedExamPage !== "") {
    if (!M.EXAM_LINKS.some((x) => x.en === c.relatedExamPage)) add("relatedExamPage", `relatedExamPage ${show(c.relatedExamPage)} isn't one of: ${M.EXAM_LINKS.map((x) => x.en).join(", ")}.`);
    else fields.relatedExamPage = c.relatedExamPage;
  }

  // en / es
  for (const lang of M.LANGS) {
    const L = lang.toUpperCase(), t = c[lang], out = { title: "", description: "", intro: "", howTo: [], keyIdeas: [], faq: [], keywords: [] };
    fields[lang] = out;
    if (!t || typeof t !== "object" || Array.isArray(t)) { add(lang, `Missing the "${lang}" section, so the ${L} page text is empty.`); continue; }
    for (const k of Object.keys(t)) if (!LANG_KEYS.includes(k)) add(lang, `${L}: unknown key "${k}" (not used; it stays in the stored config file).`, "warning");
    const f = (k) => `${lang}.${k}`;
    for (const k of ["title", "slug", "description", "intro"]) {
      const v = t[k];
      if (v === undefined || v === null || v === "") continue;
      if (typeof v !== "string") { add(f(k), `${L} ${LABEL[k]} must be text, got ${show(v)}.`); continue; }
      if (k === "slug") (lang === "es" ? (fields.slugEs = v.trim()) : (fields.slugEn = v.trim()));
      else out[k] = k === "intro" ? v.replace(/\r\n?/g, "\n").trim() : v.trim();
    }
    for (const k of ["howTo", "keyIdeas", "keywords"]) {
      const v = t[k];
      if (v === undefined) continue;
      if (!Array.isArray(v)) { add(f(k), `${L} ${LABEL[k]} must be a list, got ${show(v)}.`); continue; }
      const bad = v.filter((x) => typeof x !== "string" || (k !== "keywords" && /\n/.test(x)) || (k === "keywords" && /,/.test(x)));
      out[k] = v.filter((x) => !bad.includes(x)).map((x) => x.trim()).filter(Boolean);
      if (bad.length) add(f(k), `${L} ${LABEL[k]}: ${bad.length} item(s) can't go in the form (${k === "keywords" ? "text without commas" : "one line of text each"}): ${bad.map(show).join("; ")}.`);
    }
    if (t.faq !== undefined) {
      if (!Array.isArray(t.faq)) add(f("faq"), `${L} FAQ must be a list of {"q", "a"}, got ${show(t.faq)}.`);
      else t.faq.forEach((x, i) => {
        if (!x || typeof x !== "object" || typeof x.q !== "string" || typeof x.a !== "string" || !x.q.trim() || !x.a.trim()) add(f("faq"), `${L} FAQ item ${i + 1} needs a "q" and an "a" (text): ${show(x)}.`);
        else out.faq.push({ q: x.q.trim(), a: x.a.trim() });
      });
    }
    // required, length, slugs
    for (const k of REQUIRED) {
      const has = k === "slug" ? (lang === "es" ? fields.slugEs : fields.slugEn) : Array.isArray(out[k]) ? out[k].length : out[k];
      if (!has && !problems.some((p) => p.field === f(k))) add(f(k), `${L} ${LABEL[k]} is missing.`);
    }
    if (out.description.length > M.DESC_MAX) add(f("description"), `${L} description is ${out.description.length} characters; the limit is ${M.DESC_MAX}.`);
    const slug = lang === "es" ? fields.slugEs : fields.slugEn;
    if (slug) {
      if (!M.validSlug(slug)) {
        const fixed = M.slugify(slug);
        add(f("slug"), `${L} slug "${slug}" must be lowercase letters, numbers and hyphens.`, "error", M.validSlug(fixed) ? { suggestion: fixed } : {});
      } else {
        const taken = others_.find((o) => M.slugOf(o, lang) === slug || M.historyOf(o, lang).includes(slug));
        if (taken) add(f("slug"), `${L} slug "${slug}" is already used by "${taken[lang].title || taken.id}".`, "error", { suggestion: freeSlug(slug, lang, others_) });
      }
    }
  }
  // PDFs
  if (c.files !== undefined) {
    if (!Array.isArray(c.files)) add("files", `"files" must be a list of {"file", "en", "es"}, got ${show(c.files)}.`);
    else {
      fields.files = [];
      const seen = new Map();
      c.files.forEach((x, i) => {
        if (!x || typeof x !== "object" || typeof x.file !== "string") { add("files", `File ${i + 1} needs a "file" (the PDF's name): ${show(x)}.`); return; }
        const name = baseName(x.file.trim());
        if (!M.validFileName(name)) { add("files", M.fileNameProblem(name)); return; }
        if (seen.has(name.toLowerCase())) { add("files", `"${name}" is listed twice${seen.get(name.toLowerCase()) !== name ? ` (as "${seen.get(name.toLowerCase())}" too; names can't differ only in upper/lower case)` : ""}.`); return; }
        if (fields.files.length >= M.MAX_FILES) { add("files", `More than ${M.MAX_FILES} files; "${name}" and the rest weren't added.`); return; }
        seen.set(name.toLowerCase(), name);
        const label = (k) => (typeof x[k] === "string" ? x[k].trim() : "");
        if (!label("en") || !label("es")) add("files", `"${name}" needs an "en" and an "es" label.`);
        for (const k of Object.keys(x)) if (!["file", "en", "es"].includes(k)) add("files", `"${name}": unknown key "${k}" (not used).`, "warning");
        fields.files.push({ name, labelEn: label("en"), labelEs: label("es") });
      });
    }
  }

  // related resources (EN slugs)
  if (c.related !== undefined) {
    if (!Array.isArray(c.related)) add("related", `"related" must be a list of EN slugs, got ${show(c.related)}.`);
    else {
      fields.related = [];
      for (const x of c.related) {
        const s = typeof x === "string" ? x.trim().toLowerCase() : "";
        if (!M.SLUG_RE.test(s)) { add("related", `Related: ${show(x)} isn't a slug.`); continue; }
        if (s === fields.slugEn) { add("related", `Related: "${s}" is this resource itself (skipped).`, "warning"); continue; }
        if (fields.related.includes(s)) continue;
        const o = others_.find((d) => M.slugOf(d, "en") === s || M.historyOf(d, "en").includes(s));
        if (!o) add("related", `Related: no resource has the EN slug "${s}" yet. It's kept and shows up once that resource is published.`, "warning");
        else if (!M.isLive(o)) add("related", `Related: "${s}" isn't published, so it's skipped on the page until it is.`, "warning");
        fields.related.push(s);
        if (fields.related.length >= M.RELATED_MAX) break;
      }
    }
  }
  return { ok: true, fields, problems, file };
}

/**
 * A stored resource -> its config, in exactly the upload format (the inverse of readConfig), with the
 * keys in a fixed order so exports diff cleanly. Used by the export script and (later) the admin's
 * "Config (.json)" tab and Download button. Optional keys (relatedExamPage, files, related) are left
 * out when empty.
 */
function toConfig(doc) {
  const d = M.normalize(doc);
  const text = (lang) => {
    const t = d[lang];
    return {
      title: t.title, slug: M.slugOf(d, lang), description: t.description, intro: t.intro,
      howTo: [...t.howTo], keyIdeas: [...t.keyIdeas], faq: t.faq.map((f) => ({ q: f.q, a: f.a })), keywords: [...t.keywords],
    };
  };
  const c = { version: VERSION, file: (d.file && d.file.name) || "", subject: d.subject, levels: [...d.levels], courseTags: [...d.courseTags] };
  if (d.relatedExamPage) c.relatedExamPage = d.relatedExamPage;
  if (d.related.length) c.related = [...d.related];
  if (d.files.length) c.files = d.files.map((f) => ({ file: f.name, en: f.labelEn, es: f.labelEs }));
  c.en = text("en");
  c.es = text("es");
  return c;
}
/** toConfig as the text of a .json file (2-space indent, trailing newline). */
const configText = (doc) => `${JSON.stringify(toConfig(doc), null, 2)}\n`;

/**
 * Dropped PDFs vs. the files a config (or the editor) lists, by exact name:
 * { found: [listed and dropped], missing: [listed, not dropped], extra: [dropped, not listed] }.
 */
function matchFiles(listed, droppedNames) {
  const names = (listed || []).map((f) => (typeof f === "string" ? f : f.name));
  const dropped = [...new Set(droppedNames || [])];
  return {
    found: names.filter((n) => dropped.includes(n)),
    missing: names.filter((n) => !dropped.includes(n)),
    extra: dropped.filter((n) => !names.includes(n)),
  };
}

module.exports = { VERSION, MAX_BYTES, readConfig, toConfig, configText, parseJson, freeSlug, stem, baseName, matchFiles };
